// Rapport hebdomadaire — tableau de bord HTML enrichi, pour UN SEUL
// utilisateur — aucun appel IA, aucun appel réseau dans ce nœud. Ce nœud
// est exécuté en mode 'Run Once for Each Item' : à chaque exécution, il
// reçoit exactement UN item, correspondant au MÊME utilisateur que celui
// traité par la boucle (voir 'Boucle : un utilisateur à la fois' et
// 'Assembler les données de l'utilisateur'). Il ne fait aucune requête
// réseau et ne contient aucun this.helpers.httpRequest(...), aucun
// this.helpers.httpRequestWithAuthentication(...), aucun fetch(), aucun
// axios, aucun require(). Il ne fait AUCUNE corrélation par index ni
// itemMatching() : il n'y a jamais plus d'un utilisateur en vol à la fois
// dans ce workflow, donc aucune corrélation n'est nécessaire ici.
//
// Sécurité (n8n Cloud) : la Secret key Supabase (sb_secret_...) n'apparaît
// jamais dans ce code. Elle est appliquée uniquement par la Credential
// Custom Auth 'Supabase Service Role', attachée directement aux nœuds HTTP
// Request en amont ('Récupérer les utilisateurs Auth', 'Récupérer les
// projets/tâches/réunions de l'utilisateur') — inchangés par cette mise à
// jour.
//
// Contrat de sortie INCHANGÉ (ne pas modifier sans adapter le nœud IF
// 'E-mail à envoyer ?' et le nœud 'Envoyer le rapport hebdomadaire') :
//   - { skip: true, reason: '...' }               → aucun e-mail envoyé
//   - { skip: false, email, subject, html }        → e-mail envoyé
//
// Cette révision n'ajoute QUE des améliorations visuelles et de contenu
// (résumé intelligent, couleurs de progression, détail par projet, analyse
// enrichie, conseils plus ciblés, pied de page) : aucune donnée
// supplémentaire n'est récupérée, aucune requête réseau n'est ajoutée,
// aucune condition métier existante n'est modifiée.
//
// Hypothèses documentées (voir README > Limites) :
//  - "tâches créées" = tâches dont created_at est dans les 7 derniers jours
//    (semaine écoulée, en heure Toronto).
//  - "échéances/réunions de la semaine" = les 7 prochains jours à partir
//    d'aujourd'hui (semaine à venir).
//  - "tâches terminées" = tâches dont le statut est 'done' au moment de
//    l'exécution (la table 'tasks' ne conserve pas de date d'achèvement),
//    présenté ici comme le bilan de la semaine.
//  - Un élément renvoyé en erreur par un nœud HTTP en amont (objet
//    contenant une clé 'error', ou 'message'+'code') est filtré et ignoré.

const user = $input.item.json;

if (!user || !user.email) {
  return { json: { skip: true, reason: "no-email" } };
}

function cleanArray(value) {
  if (!Array.isArray(value)) return [];
  return value.filter(
    (item) =>
      item &&
      typeof item === "object" &&
      !("error" in item) &&
      !("message" in item && "code" in item)
  );
}

const projects = cleanArray(user.projects);
const tasks = cleanArray(user.tasks);
const meetings = cleanArray(user.meetings);

const configItems = $("Configuration ProjectFlow").all();
const config = configItems.length > 0 ? configItems[0].json : {};
const APP_BASE_URL = config.APP_BASE_URL || "";
const TZ = "America/Toronto";

function esc(value) {
  return String(value == null ? "" : value).replace(/[&<>"']/g, function (c) {
    return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
  });
}

function clamp(n, min, max) {
  return Math.max(min, Math.min(max, n));
}

function plural(n, singular, pluralForm) {
  return n === 1 ? singular : pluralForm;
}

function dateStr(d, tz) {
  return new Date(d).toLocaleDateString("en-CA", { timeZone: tz });
}

function addDaysToDateStr(ymd, days) {
  const parts = ymd.split("-").map(Number);
  const utcDate = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
  utcDate.setUTCDate(utcDate.getUTCDate() + days);
  return utcDate.toISOString().slice(0, 10);
}

function formatLongDate(d, tz) {
  return new Date(d).toLocaleDateString("fr-CA", {
    timeZone: tz,
    weekday: "long",
    day: "numeric",
    month: "long",
    year: "numeric",
  });
}

function formatShortDate(d, tz) {
  return new Date(d).toLocaleDateString("fr-CA", {
    timeZone: tz,
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

function formatTime(d, tz) {
  return new Date(d).toLocaleTimeString("fr-CA", {
    timeZone: tz,
    hour: "2-digit",
    minute: "2-digit",
  });
}

const PRIORITY_META = {
  high: { label: "Haute", color: "#ef4444", bg: "#fee2e2" },
  medium: { label: "Moyenne", color: "#d97706", bg: "#fef3c7" },
  low: { label: "Basse", color: "#16a34a", bg: "#dcfce7" },
};

function priorityMeta(priority) {
  return PRIORITY_META[priority] || { label: priority || "—", color: "#6b7280", bg: "#f3f4f6" };
}

function priorityBadge(priority) {
  const meta = priorityMeta(priority);
  return (
    '<span style="display:inline-block;padding:2px 8px;border-radius:999px;font-size:11px;' +
    'font-weight:600;color:' + meta.color + ';background:' + meta.bg + ';">' +
    esc(meta.label) +
    "</span>"
  );
}

// Couleur de la barre de progression selon le pourcentage :
// 0-30% rouge, 31-70% orange, 71-100% vert.
function progressColor(pct) {
  if (pct <= 30) return { color: "#ef4444", bg: "#fef2f2" };
  if (pct <= 70) return { color: "#f59e0b", bg: "#fffbeb" };
  return { color: "#22c55e", bg: "#f0fdf4" };
}

function progressBar(pct, color) {
  const safePct = clamp(Math.round(pct), 0, 100);
  return (
    '<div style="background:#e5e7eb;border-radius:999px;height:10px;width:100%;overflow:hidden;">' +
    '<div style="background:' + color + ';height:10px;width:' + safePct + '%;border-radius:999px;"></div>' +
    "</div>"
  );
}

function statCard(icon, label, value, color, bg) {
  return (
    '<td style="padding:6px;width:33%;" valign="top">' +
    '<div style="background:' + bg + ';border-radius:12px;padding:14px;text-align:center;border:1px solid ' + color + '22;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
    '<div style="font-size:22px;line-height:1;">' + icon + "</div>" +
    '<div style="font-size:26px;font-weight:700;color:' + color + ';margin-top:6px;">' + value + "</div>" +
    '<div style="font-size:12px;color:#4b5563;margin-top:2px;">' + esc(label) + "</div>" +
    "</div>" +
    "</td>"
  );
}

function taskRow(t) {
  const due = t.due_date ? formatShortDate(t.due_date, TZ) : "Sans échéance";
  return (
    '<li style="padding:10px 12px;border-bottom:1px solid #f1f2f4;list-style:none;display:flex;' +
    'justify-content:space-between;align-items:center;gap:8px;">' +
    '<span style="font-size:14px;color:#111827;">' + esc(t.title) + "</span>" +
    '<span style="display:flex;align-items:center;gap:8px;white-space:nowrap;">' +
    priorityBadge(t.priority) +
    '<span style="font-size:12px;color:#6b7280;">' + esc(due) + "</span>" +
    "</span>" +
    "</li>"
  );
}

function taskListSection(title, icon, list, emptyLabel) {
  const body =
    list && list.length > 0
      ? '<ul style="margin:0;padding:0;">' + list.map(taskRow).join("") + "</ul>"
      : '<p style="color:#9ca3af;font-size:13px;margin:0;padding:10px 12px;">' + esc(emptyLabel) + "</p>";
  return (
    '<div style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;margin-bottom:16px;overflow:hidden;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
    '<div style="padding:12px 16px;border-bottom:1px solid #f1f2f4;font-weight:600;color:#111827;font-size:14px;">' +
    icon + " " + esc(title) +
    ' <span style="color:#9ca3af;font-weight:400;">(' + (list ? list.length : 0) + ")</span>" +
    "</div>" +
    body +
    "</div>"
  );
}

function projectCard(p) {
  const projectTasks = tasks.filter((t) => t.project_id === p.id);
  const total = projectTasks.length;
  const done = projectTasks.filter((t) => t.status === "done").length;
  const remaining = total - done;
  const pct = total > 0 ? Math.round((done / total) * 100) : 0;
  const tier = progressColor(pct);
  return (
    '<div style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;padding:14px 16px;margin-bottom:10px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">' +
    '<span style="font-weight:600;color:#111827;font-size:14px;">' + esc(p.title) + "</span>" +
    '<span style="font-size:11px;color:#2563eb;background:#dbeafe;padding:2px 8px;border-radius:999px;font-weight:600;">' +
    esc(p.status) +
    "</span>" +
    "</div>" +
    progressBar(pct, tier.color) +
    '<div style="font-size:12px;color:#6b7280;margin-top:6px;">' +
    done + " / " + total + " " + plural(total, "tâche terminée", "tâches terminées") +
    " (" + remaining + " " + plural(remaining, "restante", "restantes") + ") — " + clamp(pct, 0, 100) + "%" +
    "</div>" +
    "</div>"
  );
}

function meetingRow(m) {
  const project = projects.find((p) => p.id === m.project_id);
  return (
    '<li style="padding:10px 12px;border-bottom:1px solid #f1f2f4;list-style:none;">' +
    '<div style="font-size:14px;color:#111827;font-weight:600;">' + esc(m.title) + "</div>" +
    '<div style="font-size:12px;color:#6b7280;margin-top:2px;">' +
    (project ? esc(project.title) + " — " : "") +
    esc(formatLongDate(m.starts_at, TZ)) + " à " + esc(formatTime(m.starts_at, TZ)) +
    "</div>" +
    "</li>"
  );
}

try {
  const now = new Date();
  const todayStr = dateStr(now, TZ);
  const weekStartStr = todayStr;
  const weekEndStr = addDaysToDateStr(todayStr, 6);
  const lastWeekStartStr = addDaysToDateStr(todayStr, -7);

  const activeProjects = projects.filter((p) => p.status === "active");

  const tasksCreated = tasks.filter((t) => {
    if (!t.created_at) return false;
    const created = dateStr(t.created_at, TZ);
    return created >= lastWeekStartStr && created <= todayStr;
  });

  const tasksDone = tasks.filter((t) => t.status === "done");
  const tasksRemaining = tasks.filter((t) => t.status !== "done");
  const tasksOverdue = tasks.filter((t) => {
    if (t.status === "done" || !t.due_date) return false;
    return dateStr(t.due_date, TZ) < todayStr;
  });

  const deadlinesThisWeek = tasks.filter((t) => {
    if (!t.due_date) return false;
    const d = dateStr(t.due_date, TZ);
    return d >= weekStartStr && d <= weekEndStr;
  });

  const meetingsThisWeek = meetings.filter((m) => {
    if (!m.starts_at) return false;
    const d = dateStr(m.starts_at, TZ);
    return d >= weekStartStr && d <= weekEndStr;
  });

  const globalPct = tasks.length > 0 ? clamp(Math.round((tasksDone.length / tasks.length) * 100), 0, 100) : 0;
  const globalTier = progressColor(globalPct);
  const totalBlocks = 16;
  const filledBlocks = clamp(Math.round((globalPct / 100) * totalBlocks), 0, totalBlocks);
  const globalBarText = "█".repeat(filledBlocks) + "░".repeat(totalBlocks - filledBlocks);

  const hasHighRemaining = tasks.some((t) => t.priority === "high" && t.status !== "done");

  // --- Résumé intelligent (haut de l'e-mail) — JavaScript pur, aucune IA ---
  const summaryParagraphs = [];
  if (tasks.length > 0) {
    summaryParagraphs.push(
      "Cette semaine, vous avez terminé " + tasksDone.length + " " +
      plural(tasksDone.length, "tâche", "tâches") + " sur " + tasks.length + "."
    );
  } else {
    summaryParagraphs.push("Aucune tâche n'a été suivie cette semaine.");
  }
  summaryParagraphs.push("Votre progression globale est de " + globalPct + "%.");
  if (tasks.length > 0 && tasksRemaining.length === 0) {
    summaryParagraphs.push("Félicitations ! Toutes vos tâches sont terminées.");
  } else if (globalPct >= 80) {
    summaryParagraphs.push("Excellente semaine ! Vous avez terminé la majorité de vos tâches. Continuez sur cette lancée.");
  } else if (globalPct >= 50) {
    summaryParagraphs.push("Bonne progression. Quelques tâches restent à terminer. Vous êtes sur la bonne voie.");
  } else {
    summaryParagraphs.push("La progression est encore limitée. Essayez de prioriser les tâches importantes cette semaine.");
  }
  if (tasksOverdue.length > 0) {
    summaryParagraphs.push(
      "Attention : " + tasksOverdue.length + " " +
      plural(tasksOverdue.length, "tâche est", "tâches sont") +
      " actuellement en retard. Pensez à commencer votre semaine par " +
      plural(tasksOverdue.length, "celle-ci", "celles-ci") + "."
    );
  }

  // --- 7. Analyse automatique (aucune IA — conditions JavaScript pures) ---
  const analysisMessages = [];
  analysisMessages.push({
    icon: "✅",
    text: "Vous avez terminé " + tasksDone.length + " " + plural(tasksDone.length, "tâche", "tâches") + " cette semaine.",
    color: "#16a34a",
  });
  analysisMessages.push({
    icon: "📈",
    text: "Votre progression est de " + globalPct + "%.",
    color: "#2563eb",
  });
  if (tasksOverdue.length > 0) {
    analysisMessages.push({
      icon: "🚨",
      text: tasksOverdue.length + " " + plural(tasksOverdue.length, "tâche est", "tâches sont") + " en retard.",
      color: "#dc2626",
    });
  } else {
    analysisMessages.push({ icon: "🙌", text: "Aucune tâche en retard, bravo !", color: "#16a34a" });
  }
  if (meetingsThisWeek.length > 0) {
    analysisMessages.push({
      icon: "📅",
      text: meetingsThisWeek.length + " " + plural(meetingsThisWeek.length, "réunion est prévue", "réunions sont prévues") + " cette semaine.",
      color: "#0891b2",
    });
  } else {
    analysisMessages.push({ icon: "📅", text: "Aucune réunion n'est prévue cette semaine.", color: "#6b7280" });
  }
  if (hasHighRemaining) {
    analysisMessages.push({ icon: "⚡", text: "Vous devriez commencer par les tâches de priorité Haute.", color: "#d97706" });
  } else if (tasks.length > 0 && tasksRemaining.length === 0) {
    analysisMessages.push({ icon: "🎉", text: "Toutes vos tâches sont terminées, excellent travail !", color: "#16a34a" });
  }

  // --- 8. Conseils intelligents (uniquement les conseils pertinents) ---
  const tips = [];
  if (tasksOverdue.length > 0) {
    tips.push("Commencez par les tâches en retard.");
  }
  if (hasHighRemaining) {
    tips.push("Traitez d'abord les tâches à haute priorité.");
  }
  if (meetingsThisWeek.length > 0) {
    tips.push("Préparez vos réunions à l'avance.");
  }
  if (globalPct < 50) {
    tips.push("Essayez de terminer au moins une tâche importante chaque jour.");
  }
  if (tips.length === 0) {
    tips.push("Rien d'urgent : profitez-en pour planifier la suite.");
  }

  const linkHtml = APP_BASE_URL
    ? '<p style="text-align:center;margin:20px 0 0;"><a href="' + esc(APP_BASE_URL) + '/" ' +
      'style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;padding:10px 20px;' +
      'border-radius:8px;font-size:13px;font-weight:600;box-shadow:0 1px 2px rgba(0,0,0,0.08);">Voir mes projets dans ProjectFlow</a></p>'
    : "";

  const html =
    '<div style="font-family:-apple-system,BlinkMacSystemFont,\'Segoe UI\',Roboto,Arial,sans-serif;color:#111827;max-width:640px;' +
    'margin:0 auto;background:#f9fafb;padding:20px;">' +

    // 1. En-tête
    '<div style="text-align:center;margin-bottom:20px;">' +
    '<h1 style="font-size:22px;margin:0 0 6px;color:#111827;">📊 ProjectFlow — Rapport hebdomadaire d\'avancement</h1>' +
    '<p style="font-size:14px;color:#6b7280;margin:0;">Résumé de votre activité de la semaine écoulée et aperçu de la semaine à venir.</p>' +
    '<p style="font-size:12px;color:#9ca3af;margin:8px 0 0;">Généré le ' + esc(formatLongDate(now, TZ)) + ' à ' + esc(formatTime(now, TZ)) + '</p>' +
    '</div>' +

    // Résumé intelligent
    '<div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:12px;padding:16px;margin-bottom:16px;">' +
    summaryParagraphs.map((p) => '<p style="margin:4px 0;font-size:13px;color:#1e3a8a;">' + esc(p) + '</p>').join("") +
    '</div>' +

    // 2. Cartes statistiques
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:16px;">' +
    '<tr>' +
    statCard("📁", "Projets actifs", activeProjects.length, "#2563eb", "#eff6ff") +
    statCard("✅", "Tâches terminées", tasksDone.length, "#16a34a", "#f0fdf4") +
    statCard("🕒", "Tâches restantes", tasksRemaining.length, "#d97706", "#fffbeb") +
    '</tr>' +
    '<tr>' +
    statCard("🆕", "Créées cette semaine", tasksCreated.length, "#7c3aed", "#f5f3ff") +
    statCard("📅", "Réunions cette semaine", meetingsThisWeek.length, "#0891b2", "#ecfeff") +
    statCard("🚨", "Tâches en retard", tasksOverdue.length, "#dc2626", "#fef2f2") +
    '</tr>' +
    '</table>' +

    // 3. Progression globale (couleur selon le pourcentage : rouge/orange/vert)
    '<div style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-bottom:16px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
    '<div style="font-weight:600;font-size:14px;color:#111827;margin-bottom:8px;">Progression globale : <span style="color:' + globalTier.color + ';">' + globalPct + ' %</span></div>' +
    progressBar(globalPct, globalTier.color) +
    '<div style="font-family:monospace;font-size:12px;color:#6b7280;margin-top:6px;">' + globalBarText + ' ' + globalPct + '%</div>' +
    '</div>' +

    // 4. Projets actifs
    '<div style="margin-bottom:4px;font-weight:600;font-size:14px;color:#111827;">📁 Projets actifs (' + activeProjects.length + ')</div>' +
    '<div style="margin-bottom:16px;">' +
    (activeProjects.length > 0
      ? activeProjects.map(projectCard).join("")
      : '<p style="color:#9ca3af;font-size:13px;">Aucun projet actif.</p>') +
    '</div>' +

    // 5. Résumé des tâches
    taskListSection("Tâches terminées", "✅", tasksDone, "Aucune tâche terminée cette semaine.") +
    taskListSection("Tâches restantes", "🕒", tasksRemaining, "Aucune tâche restante.") +
    taskListSection("Tâches créées cette semaine", "🆕", tasksCreated, "Aucune tâche créée cette semaine.") +
    taskListSection("Tâches en retard", "🚨", tasksOverdue, "Aucune tâche en retard.") +

    // 6. Réunions
    '<div style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;margin-bottom:16px;overflow:hidden;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
    '<div style="padding:12px 16px;border-bottom:1px solid #f1f2f4;font-weight:600;color:#111827;font-size:14px;">' +
    '📅 Réunions de la semaine <span style="color:#9ca3af;font-weight:400;">(' + meetingsThisWeek.length + ')</span>' +
    '</div>' +
    (meetingsThisWeek.length > 0
      ? '<ul style="margin:0;padding:0;">' + meetingsThisWeek.map(meetingRow).join("") + '</ul>'
      : '<p style="color:#9ca3af;font-size:13px;margin:0;padding:10px 16px;">Aucune réunion prévue cette semaine.</p>') +
    '</div>' +

    // 7. Analyse automatique (enrichie)
    '<div style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;padding:14px 16px;margin-bottom:16px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
    '<div style="font-weight:600;font-size:14px;color:#111827;margin-bottom:8px;">🤖 Analyse de votre semaine</div>' +
    analysisMessages.map((m) => '<p style="margin:4px 0;font-size:13px;color:' + m.color + ';">' + m.icon + ' ' + esc(m.text) + '</p>').join("") +
    '</div>' +

    // 8. Conseils intelligents
    '<div style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;padding:14px 16px;margin-bottom:16px;box-shadow:0 1px 2px rgba(0,0,0,0.04);">' +
    '<div style="font-weight:600;font-size:14px;color:#111827;margin-bottom:8px;">💡 Conseils</div>' +
    '<ul style="margin:0;padding-left:18px;">' +
    tips.map((tip) => '<li style="font-size:13px;color:#374151;margin:4px 0;">' + esc(tip) + '</li>').join("") +
    '</ul>' +
    '</div>' +

    linkHtml +

    // 9. Pied de page
    '<div style="text-align:center;margin-top:24px;padding-top:16px;border-top:1px solid #e5e7eb;">' +
    '<p style="font-size:12px;color:#9ca3af;margin:0;font-weight:600;">ProjectFlow</p>' +
    '<p style="font-size:11px;color:#9ca3af;margin:6px 0 0;">Merci d\'utiliser ProjectFlow.</p>' +
    '<p style="font-size:11px;color:#9ca3af;margin:2px 0 0;">Votre assistant intelligent de gestion de projets.</p>' +
    '<p style="font-size:11px;color:#9ca3af;margin:2px 0 0;">Rapport généré automatiquement chaque lundi.</p>' +
    '</div>' +

    '</div>';

  return {
    json: {
      skip: false,
      email: user.email,
      subject: "ProjectFlow — Rapport hebdomadaire d'avancement",
      html: html,
    },
  };
} catch (err) {
  console.error("[weekly-progress-report] Échec de génération du rapport pour " + user.email + ":", err);
  return { json: { skip: true, email: user.email, reason: "build-error" } };
}
